features=[]; targets=[]
for I,O in data:
 A=np.array(I,dtype=int); B=np.array(O,dtype=int)
 for r in range(6):
  for c in range(5):
   feat=[]
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     rr,cc=r+dr,c+dc
     feat.append(int(0<=rr<6 and 0<=cc<5 and A[rr,cc]))
   feat.append(1)
   features.append(feat); targets.append(int(B[r,c]))
F=np.array(features,dtype=np.uint8); T=np.array(targets,dtype=np.uint8)
def gf2solve(F,T):
 M=np.concatenate([F.copy(),T[:,None]],axis=1); m,n=F.shape; piv=[]; row=0
 for col in range(n):
  cand=np.where(M[row:,col]==1)[0]
  if not len(cand): continue
  k=row+int(cand[0]); M[[row,k]]=M[[k,row]]
  for rr in range(m):
   if rr!=row and M[rr,col]: M[rr]^=M[row]
  piv.append(col); row+=1
  if row==m: break
 if np.any((M[:, :n].sum(axis=1)==0)&(M[:,n]==1)): return None, len(piv)
 sol=np.zeros(n,dtype=np.uint8)
 for i,col in enumerate(piv): sol[col]=M[i,n]
 return sol,len(piv)
sol,rank=gf2solve(F,T)
sol,rank, (int((F@sol%2!=T).sum()) if sol is not None else None)

